pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Split into lines; if this yields nothing (e.g., empty string),
            // return a single-element list to ensure non-empty.
            let mut lines: Vec<String> = if keepends {
                s.split_inclusive('\n').map(|p| p.to_string()).collect()
            } else {
                s.split('\n').map(|p| p.to_string()).collect()
            };

            if lines.is_empty() {
                lines.push(String::new());
            }
            lines
        })
        .collect()
}